import React from 'react'
import {Alert, StyleSheet, type StyleProp, type ViewStyle} from 'react-native'
import {
  ImageLibraryOptions,
  ImagePickerResponse,
  launchImageLibrary,
} from 'react-native-image-picker'
import {IconButton} from 'react-native-paper'
import {
  requestPhotoPermission,
  showPermissionBlockedAlert,
} from '../../utils/permission'
interface propTypes {
  iconSize?: number
  onChange?: (result: ImagePickerResponse) => void
  options?: Omit<ImageLibraryOptions, 'mediaType'>
  style?: StyleProp<ViewStyle>
  disabled?: boolean
}

export default function UploadButton({
  iconSize = 25,
  onChange,
  options,
  style,
  disabled,
}: propTypes) {
  const pickFile = async () => {
    if (disabled) return
    try {
      const hasPermission = await requestPhotoPermission()
      if (hasPermission?.status == 'BLOCKED')
        return showPermissionBlockedAlert({})
      if (!hasPermission?.ok)
        return Alert.alert('권한 확인', hasPermission?.reason)
      const result = await launchImageLibrary({mediaType: 'photo', ...options})
      if (result.didCancel || !result.assets?.[0]?.uri) return
      if (onChange) onChange(result)
      //   setPreviewUrl(result.assets[0].uri!)
    } catch (e) {
      console.log('이미지피커 오류: ', e)
    }
  }

  return (
    <>
      <IconButton
        icon={'plus'}
        size={iconSize}
        style={[styles.iconButton, {width: iconSize, height: iconSize}, style]}
        contentStyle={{width: iconSize, height: iconSize}}
        onPress={pickFile}
        disabled={disabled}
      />
    </>
  )
}

const styles = StyleSheet.create({
  uploadIcon: {
    backgroundColor: '#FFF',
    padding: 0,
    // borderRadius: 20,
  },
  iconButton: {
    // backgroundColor: COLORS.outerColor,
    margin: 0,
    padding: 0,
  },
})
